/**
 * The one API client: every call from the frontend to the backend goes through the named methods of
 * `api`, and all of them share `unwrap` (same-origin credentials, one error handling).
 *
 * Built on openapi-fetch and typed with the types generated from the backend's OpenAPI schema
 * (./types.ts, regenerated by ./scripts/start.sh and ./scripts/test.sh), so a wrong path, body or
 * response fails the type check. Components import the backend's shapes from here, never from
 * ./types.ts directly. A failed call throws an ApiError whose message is the backend's user message
 * (`detail`), ready to show. A 401 means the session ended: the browser goes to the login page.
 */
import createClient from "openapi-fetch";
import type { components, paths } from "./types";

type Schemas = components["schemas"];
export type AppConfig = Schemas["AppConfig"];
export type Me = Schemas["Me"];
export type SignupRequest = Schemas["SignupRequest"];
export type LoginRequest = Schemas["LoginRequest"];
export type ConversationSummary = Schemas["ConversationSummary"];
export type AccessCodeRow = Schemas["AccessCodeRow"];
export type CreatedAccessCode = Schemas["CreatedAccessCode"];
export type Settings = Schemas["Settings"];
export type SettingsPage = Schemas["SettingsPage"];
export type Option = Schemas["Option"];
export type Catalog = Schemas["Catalog"];
export type CatalogEdit = Schemas["CatalogEdit"];
export type CatalogQuestionEdit = Schemas["CatalogQuestionEdit"];
export type ConversationView = Schemas["ConversationView"];
export type TranscriptMessage = Schemas["TranscriptMessage"];
export type StartResponse = Schemas["StartResponse"];
export type EndRequest = Schemas["EndRequest"];
export type ToolName = Schemas["ToolName"];
export type ConversationState = ConversationView["state"];
export type EndReason = NonNullable<ConversationView["end_reason"]>;
export type Speaker = TranscriptMessage["speaker"];
export type TeamConversationRow = Schemas["TeamConversationRow"];
export type TeamConversationDetail = Schemas["TeamConversationDetail"];
export type Questionnaire = Schemas["Questionnaire"];
export type QuestionnaireEntry = Schemas["QuestionnaireEntry"];

const UNREACHABLE = "Der Server ist nicht erreichbar. Bitte prüfen Sie Ihre Verbindung.";
const UNEXPECTED = "Etwas ist schiefgelaufen. Bitte versuchen Sie es erneut.";

export class ApiError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

/** The text to show for any error a component caught: the backend's message, or a generic one. */
export function errorMessage(error: unknown): string {
  return error instanceof ApiError ? error.message : UNEXPECTED;
}

const client = createClient<paths>({ credentials: "same-origin" });

async function unwrap<Data>(request: Promise<{ data?: Data; error?: unknown; response: Response }>): Promise<Data> {
  let result;
  try {
    result = await request;
  } catch {
    throw new ApiError(UNREACHABLE, 0); // no answer at all: network down or server unreachable
  }
  const { data, error, response } = result;
  if (response.ok) return data as Data;
  if (response.status === 401) window.location.assign("/login");
  // An error body is an ErrorResponse, except when no backend answered (for example the dev
  // server's proxy while the backend restarts), so `detail` is checked at runtime.
  const detail = typeof error === "object" && error !== null && "detail" in error ? error.detail : undefined;
  throw new ApiError(typeof detail === "string" ? detail : UNEXPECTED, response.status);
}

const conversationPath = (id: string) => ({ path: { conversation_id: id } });

export const api = {
  // `signal` lets the device check give up after its timeout.
  appConfig: (signal?: AbortSignal) => unwrap(client.GET("/api/app-config", { signal })),
  me: () => unwrap(client.GET("/api/auth/me")),
  signup: (body: SignupRequest) => unwrap(client.POST("/api/auth/signup", { body })),
  login: (body: LoginRequest) => unwrap(client.POST("/api/auth/login", { body })),
  logout: () => unwrap(client.POST("/api/auth/logout")),
  myConversations: () => unwrap(client.GET("/api/my/conversations")),
  unlockConversation: (code: string) => unwrap(client.POST("/api/my/conversations", { body: { code } })),
  conversation: (id: string) => unwrap(client.GET("/api/my/conversations/{conversation_id}", { params: conversationPath(id) })),
  startConversation: (id: string, sdp: string) =>
    unwrap(client.POST("/api/my/conversations/{conversation_id}/start", { params: conversationPath(id), body: { sdp } })),
  // keepalive: the report still reaches the backend while the tab is being closed (call/useCall.ts).
  endConversation: (id: string, reason: EndRequest["reason"]) =>
    unwrap(client.POST("/api/my/conversations/{conversation_id}/end", {
      params: conversationPath(id),
      body: { reason },
      keepalive: true,
    })),
  teamConversations: () => unwrap(client.GET("/api/team/conversations")),
  teamConversation: (id: string) =>
    unwrap(client.GET("/api/team/conversations/{conversation_id}", { params: conversationPath(id) })),
  accessCodes: () => unwrap(client.GET("/api/team/access-codes")),
  createAccessCode: (email: string) => unwrap(client.POST("/api/team/access-codes", { body: { email } })),
  settings: () => unwrap(client.GET("/api/team/settings")),
  saveSettings: (body: Settings) => unwrap(client.PUT("/api/team/settings", { body })),
  resetSettings: () => unwrap(client.POST("/api/team/settings/reset")),
  catalog: () => unwrap(client.GET("/api/team/catalog")),
  saveCatalog: (body: CatalogEdit) => unwrap(client.PUT("/api/team/catalog", { body })),
  resetCatalog: () => unwrap(client.POST("/api/team/catalog/reset")),
};
